theme.css:
:root {
  --background: #f7f7fd;
  --foreground: #303044;
  --card: #ecebff;
  --card-foreground: #303044;
  --popover: #ffffff;
  --popover-foreground: #303044;
  --primary: #000000;
  --primary-foreground: #ffffff;
  --secondary: #e8e5f9;
  --secondary-foreground: #534d73;
  --muted: #f2f2f8;
  --muted-foreground: #727284;
  --accent: #e0e8f7;
  --accent-foreground: #303044;
  --destructive: #ff1a40;
  --destructive-foreground: #ffffff;
  --border: #e3e3ed;
  --input: #e3e3ed;
  --ring: #7d6eb7;
  --chart-1: #7757f4;
  --chart-2: #ada2e6;
  --chart-3: #7a7bd2;
  --chart-4: #9490df;
  --chart-5: #5b579c;
  --radius: 0rem;
  --sidebar: #f7f7fd;
  --sidebar-foreground: #303044;
  --sidebar-primary: #7d6eb7;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #e0e8f7;
  --sidebar-accent-foreground: #303044;
  --sidebar-border: #e3e3ed;
  --sidebar-ring: #7d6eb7;
  --font-sans: Roboto, ui-sans-serif, sans-serif, system-ui;
  --font-serif: Almendra, ui-serif, serif;
  --font-mono: Roboto Mono, ui-monospace, monospace;
  --shadow-color: #34344b;
  --shadow-opacity: 0.12;
  --shadow-blur: 10px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 4px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
}

.dark {
  --background: #15151e;
  --foreground: #e6e6f1;
  --card: #1e1e2a;
  --card-foreground: #e6e6f1;
  --popover: #1e1e2a;
  --popover-foreground: #e6e6f1;
  --primary: #b2a5e9;
  --primary-foreground: #15151e;
  --secondary: #35334d;
  --secondary-foreground: #cfcef3;
  --muted: #29293d;
  --muted-foreground: #a6a6ba;
  --accent: #3a3a56;
  --accent-foreground: #e6e6f1;
  --destructive: #dd7687;
  --destructive-foreground: #ffffff;
  --border: #37374b;
  --input: #37374b;
  --ring: #b2a5e9;
  --chart-1: #b2a5e9;
  --chart-2: #8991bb;
  --chart-3: #81b2d9;
  --chart-4: #62a19b;
  --chart-5: #e494c2;
  --radius: 0rem;
  --sidebar: #1e1e2a;
  --sidebar-foreground: #e6e6f1;
  --sidebar-primary: #b2a5e9;
  --sidebar-primary-foreground: #15151e;
  --sidebar-accent: #3a3a56;
  --sidebar-accent-foreground: #e6e6f1;
  --sidebar-border: #37374b;
  --sidebar-ring: #b2a5e9;
  --font-sans: Inter, sans-serif;
  --font-serif: Almendra, ui-serif, serif;
  --font-mono: Roboto Mono, ui-monospace, monospace;
  --shadow-color: #34344b;
  --shadow-opacity: 0.12;
  --shadow-blur: 10px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 4px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-radius: var(--radius);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
  --color-font-sans: var(--font-sans);
  --color-font-serif: var(--font-serif);
  --color-font-mono: var(--font-mono);
  --color-shadow-color: var(--shadow-color);
  --color-shadow-opacity: var(--shadow-opacity);
  --color-shadow-blur: var(--shadow-blur);
  --color-shadow-spread: var(--shadow-spread);
  --color-shadow-offset-x: var(--shadow-offset-x);
  --color-shadow-offset-y: var(--shadow-offset-y);
  --color-letter-spacing: var(--letter-spacing);
  --color-spacing: var(--spacing);
}
